/**
 * Types mirroring the kernel `dataload` package JSON (profile.go, plan.go,
 * ledger.go, media.go, review.go, registry.go) and the OPS `/api/dataload`
 * envelope. `src/__fixtures__/ops/*.json` are the server's own responses (golden,
 * generated by `handlers/dataload_contract_test.go` in OPS); `contract.test.ts`
 * types and normalizes them, so a shape change breaks CI. Nothing here knows a
 * niche or a source platform: those live in declarative profiles (data).
 */

/** Stable cleaning rule names (profile.go `knownClean`), plus the parameterized `drop_lines:<regex>`. */
export const CLEAN_RULES = [
  'trim',
  'collapse_spaces',
  'unescape_newlines',
  'strip_html',
  'trim_quotes',
  'null_if_emptyish',
  'lower',
  'upper',
  'sanitize_html',
  'collapse_blank_lines',
  'auto_paragraphs',
] as const

export type CleanRule = (typeof CLEAN_RULES)[number] | `drop_lines:${string}`

export type FieldType = 'text' | 'number' | 'boolean' | 'date' | 'email'

export interface DataloadField {
  /** Destination field (dotted path allowed). */
  target: string
  /** Source columns, first match wins. */
  from: string[]
  type?: FieldType
  required?: boolean
  clean?: CleanRule[]
  /** Value translation table (source value -> destination value). */
  values?: Record<string, string>
  transform?: string
  /** Value is a media URL (or a list) to download and back up. */
  media?: boolean
  sep?: string
  default?: unknown
  /** Rules that always run last (after `clean` and an override's `cleanAdd`). */
  finish?: CleanRule[]
  /** Splits the cleaned cell into a list of non-empty texts. */
  split?: string
  /** Computed from other columns (kernel `Derive`); a derived field has no `from`. Opaque here. */
  derive?: Record<string, unknown>
}

export interface OrderRule {
  field: string
  rank: string[]
}

export interface DataloadProfile {
  name: string
  version: string
  entity: string
  key: string[]
  fields: DataloadField[]
  defaults?: Record<string, unknown>
  clean?: CleanRule[]
  ignoreHeaders?: string[]
  maxRows?: number
  /** Row cap for a streamed source (not loaded in memory). */
  maxStreamRows?: number
  applyOrder?: OrderRule[]
  /**
   * What to do when the same identity appears in several rows of the file:
   * `review` (default) loads none of them and sends the first to review
   * (`duplicate_key`), `first` loads the first and drops the rest.
   */
  duplicates?: DuplicatesPolicy
}

export type DuplicatesPolicy = 'review' | 'first'

/** A profile version in the registry: `org` empty = the host's shared base catalog. */
export interface ProfileKey {
  org?: string
  name: string
  version: string
}

/** One published version as `GET /profiles` lists it (no mapping body). */
export interface ProfileSummary extends ProfileKey {
  org: string
  base?: ProfileKey
  entity?: string
  hasExtract: boolean
  fingerprint: string
  note?: string
  createdBy?: string
  createdAt: string
  /** Shared by the host for every organization (read-only, referenced as `base/name@version`). */
  shared: boolean
}

/** A full published version (kernel `StoredProfile`). Versions are immutable. */
export interface StoredProfileVersion extends ProfileKey {
  base?: ProfileKey
  profile?: DataloadProfile
  overrides?: DataloadOverrides
  extract?: Record<string, unknown>
  note?: string
  fingerprint?: string
  createdBy?: string
  createdAt?: string
}

/**
 * Publishes a NEW immutable version: a full `profile`, or a `base` plus `overrides`.
 * Publishing the same content again is a no-op; reusing a name+version with other
 * content is rejected (409).
 */
export interface PublishVersionRequest {
  name: string
  version: string
  base?: ProfileKey
  profile?: DataloadProfile
  overrides?: DataloadOverrides
  extract?: Record<string, unknown>
  note?: string
}

/** Per-organization adjustments over a base profile. */
export interface DataloadOverrides {
  org?: string
  ignoreHeaders?: string[]
  rename?: Record<string, string[]>
  fields?: DataloadField[]
  drop?: string[]
  defaults?: Record<string, unknown>
  /** Replaces the profile's global clean rules when present. */
  clean?: CleanRule[]
  /** target -> rules appended to that field's `clean`. */
  cleanAdd?: Record<string, CleanRule[]>
  /** target -> extra value translations (they win over the profile's). */
  valuesAdd?: Record<string, Record<string, string>>
  /** Replaces the profile's `duplicates` policy when present. */
  duplicates?: DuplicatesPolicy
}

export type SourceFormat = 'csv' | 'json' | 'bundle'

/** The data to load, sent as text. `path` is only used by `bundle` (dotted path to the rows array). */
export interface InlineSourceInput {
  format: SourceFormat
  name: string
  content: string
  path?: string
}

/** A file already uploaded in parts (`uploadSourceFile`): the server reads it by id. */
export interface UploadedSourceInput {
  format: SourceFormat
  name: string
  uploadId: string
  path?: string
}

/** A source the server already stored (the `source` id a dry-run returns): nothing is re-sent. */
export interface StoredSourceInput {
  id: string
}

/** What the person picked (a file read inline or uploaded in parts). */
export type DataloadSourceInput = InlineSourceInput | UploadedSourceInput

/** What a request can carry as `source`: the picked file, or the id of one the server already stored. */
export type RequestSource = DataloadSourceInput | StoredSourceInput

export const isUploadedSource = (s: RequestSource | undefined): s is UploadedSourceInput => !!s && 'uploadId' in s
export const isStoredSource = (s: RequestSource | undefined): s is StoredSourceInput => !!s && 'id' in s && !('content' in s) && !('uploadId' in s)

export type PlanAction = 'create' | 'update' | 'unchanged' | 'invalid' | 'duplicate' | 'review'

/** `revisar` blocks the automatic load of the row; `info` only informs. */
export type ReviewSeverity = 'revisar' | 'info'

/** A reason why a row needs (or deserves) a person's look (extract.go `ReviewItem`). */
export interface ReviewItem {
  code: string
  field?: string
  severity: ReviewSeverity
  detail?: string
  /** Stable code and parameters of `detail`, to translate it. */
  detailCode?: string
  detailParams?: Record<string, unknown>
}

export interface RowIssue {
  row: number
  column?: string
  message: string
  /** Stable code (`importer.*` / `dataload.*`) and parameters of `message`, to translate it. */
  code?: string
  params?: Record<string, unknown>
}

export interface FieldDiff {
  field: string
  old: unknown
  new: unknown
}

export interface RowPlan {
  /** 1-based over data rows. */
  row: number
  key?: string
  action: PlanAction
  hash?: string
  record?: Record<string, unknown>
  /** field -> source URLs that will be backed up. */
  media?: Record<string, string[]>
  diffs: FieldDiff[]
  issues: RowIssue[]
  /** Reasons from the extract stage (`revisar` and `info`). */
  review: ReviewItem[]
  /** Only on `review` rows: what applying it would do (create, update or unchanged). */
  outcome?: PlanAction
  /** Only on `review` rows: the destination fingerprint when it was planned. */
  targetHash?: string
}

/** One page of a stored plan (`GET /runs/:id/plan?action=&offset=&limit=`); `total` counts the filtered rows. */
export interface PlanPage {
  entity: string
  profile: string
  profileVersion: string
  planHash: string
  inputHash: string
  counts: Partial<Record<PlanAction, number>>
  ignoredColumns: number
  mediaUrls: number
  total: number
  offset: number
  limit: number
  rows: RowPlan[]
}

export interface PlanPageQuery {
  action?: PlanAction
  offset?: number
  /** Server default 100. */
  limit?: number
}

export interface DataloadPlan {
  org: string
  entity: string
  profile: string
  profileVersion: string
  profileHash: string
  source: string
  inputHash: string
  planHash: string
  extractHash?: string
  rows: RowPlan[]
  counts: Partial<Record<PlanAction, number>>
  ignoredColumns: number
  mediaUrls: number
}

export type RunState = 'queued' | 'running' | 'succeeded' | 'failed' | 'canceled'
/** `apply_reviewed` writes the rows a person approved in the review queue. */
export type RunMode = 'dry_run' | 'apply' | 'apply_reviewed'

export interface RunProgress {
  total: number
  done: number
  created: number
  updated: number
  unchanged: number
  invalid: number
  duplicates: number
  mediaQueued: number
  /** Valid rows waiting for a decision; they are never written on their own. */
  review?: number
  /** `apply_reviewed` only: approved rows not written because the destination changed after the decision. */
  superseded?: number
}

/** A row waiting for a decision, as listed in its run (up to 200; the full count is `progress.review`). */
export interface ReviewNote {
  row: number
  key: string
  outcome?: PlanAction
  items: ReviewItem[]
}

/** Durable per-batch resume point of a large run. */
export interface RunCheckpoint {
  batches: number
  rows: number
  lastKey?: string
  resumes?: number
  /** Rows a resume recovered from apply marks written after the last checkpoint. */
  recovered?: number
  updatedAt: string
}

export interface DataloadRun {
  id: string
  key: string
  org: string
  mode: RunMode
  state: RunState
  actor?: string
  profile: string
  profileVersion: string
  profileHash: string
  overridesHash?: string
  source: string
  inputHash: string
  planHash?: string
  extractHash?: string
  progress: RunProgress
  issues: RowIssue[]
  review: ReviewNote[]
  checkpoint?: RunCheckpoint
  error?: string
  /** Stable code and parameters of `error` (kernel catalog), to translate it. */
  errorCode?: string
  errorParams?: Record<string, unknown>
  /** Id of the run that already resolved this very input: this one wrote nothing. */
  replayOf?: string
  /** Registry version the run used (pin it to apply exactly what was simulated). */
  registry?: { key: ProfileKey; fingerprint: string }
  createdAt: string
  /** The kernel serializes unset times as 0001-01-01; use `parseTime`. */
  startedAt?: string
  finishedAt?: string
}

export type EntryStatus = 'ok' | 'missing' | 'corrupt'

export interface ManifestEntry {
  org: string
  sourceUrl: string
  sha256: string
  bytes: number
  contentType: string
  storedName: string
  fetchedAt: string
  verifiedAt: string
  status: EntryStatus
  etag?: string
  lastModified?: string
  /** Last time the origin confirmed this original is current. */
  validatedAt?: string
  /** Earlier originals of the same URL (oldest first), kept intact. */
  revisions?: { sha256: string; bytes: number; contentType: string; storedName: string; fetchedAt: string; etag?: string; lastModified?: string }[]
}

export interface VerifyReport {
  checked: number
  ok: number
  missing: ManifestEntry[]
  corrupt: ManifestEntry[]
}

export type MediaState = 'pending' | 'running' | 'done' | 'dead'

export interface MediaQueueStats {
  pending: number
  running: number
  done: number
  dead: number
}

export interface MediaJob {
  id: string
  runId?: string
  key: string
  field: string
  index: number
  url: string
  state: MediaState
  attempts: number
  lastError?: string
  /** Stable code of `lastError` when it comes from the engine (absent for network or origin errors). */
  lastErrorCode?: string
  nextAttempt: string
  sha256?: string
  deriveError?: string
  /** Pending revalidation mode (`conditional` / `refetch`), cleared when it finishes. */
  revalidate?: 'conditional' | 'refetch'
  /** What the last successful attempt did (new, fresh, not_modified, unchanged, replaced, stale). */
  outcome?: string
  updatedAt: string
}

/** Status of the media backup: queue + manifest summary (+ dead jobs to inspect). */
export interface MediaBackupStatus {
  queue: MediaQueueStats
  manifest: { total: number; ok: number; missing: number; corrupt: number; bytes: number }
  /** Jobs that died (definitive failure or exhausted attempts), newest first. */
  dead: MediaJob[]
}

/** Request shared by dry-run and execute. `profile` is a registered profile name or an inline profile. */
export interface DataloadRequest {
  profile: string | DataloadProfile
  overrides?: DataloadOverrides
  source: RequestSource
}

export interface ExecuteRequest extends DataloadRequest {
  /**
   * The `planHash` the person reviewed. The server answers 409 (`isPlanChanged`)
   * if the plan it would apply now is a different one: simulate again.
   */
  expectPlanHash?: string
  /** Apply even if an identical successful run exists (the diff keeps it safe). */
  force?: boolean
  /** Apply nothing if any row is invalid. */
  failOnInvalid?: boolean
}

export interface DryRunResult {
  plan: DataloadPlan
  run: DataloadRun
  /** Id of the stored source: execute with `{ source: { id } }` instead of sending it again. */
  source?: string
}

/** `applying`: reserved by an apply in flight (nobody can decide it meanwhile). */
export type ReviewState = 'pending' | 'approved' | 'applying' | 'rejected' | 'applied' | 'superseded'

/** States in which a person can still decide (approved can be flipped until it is applied). */
export const OPEN_REVIEW_STATES: readonly ReviewState[] = ['pending', 'approved', 'rejected']

/** A row held for a later decision (review.go `ReviewEntry`). */
export interface ReviewEntry {
  org: string
  entity: string
  key: string
  profile: string
  profileVersion: string
  profileHash: string
  /** Run that planned the row; its stored plan has the field diff. */
  runId: string
  row: number
  /** Fingerprint of the row; a decision must carry the one the person saw. */
  hash: string
  /** Destination fingerprint when it was planned; an apply skips the row if it changed since. */
  baseHash?: string
  record: Record<string, unknown>
  media?: Record<string, string[]>
  items: ReviewItem[]
  outcome?: PlanAction
  state: ReviewState
  decidedBy?: string
  decidedAt?: string
  note?: string
  appliedRun?: string
  createdAt: string
  updatedAt: string
}

export interface ReviewFilter {
  entity?: string
  state?: ReviewState
  runId?: string
  /** Only entries carrying that review code. */
  code?: string
  /** Page size; the server caps it (500). */
  limit?: number
  /** `next` of the previous page. */
  cursor?: string
}

/** One page of the review queue with the counts by state. */
export interface ReviewPage {
  items: ReviewEntry[]
  counts: Partial<Record<ReviewState, number>>
  /** Cursor of the next page; absent on the last one. */
  next?: string
}

/** An explicit decision on one row. `hash` must be the `ReviewEntry.hash` the person saw. */
export interface ReviewDecision {
  entity: string
  key: string
  hash: string
  approve: boolean
  note?: string
}

/** Server-side state of a chunked upload. */
export interface UploadSession {
  id: string
  name: string
  size: number
  /** Bytes per part chosen by the server (the last part may be shorter). */
  chunkSize: number
  /** 0-based indexes of the parts the server already has (for resume). */
  received: number[]
  /** Set once completed: sha256 of the whole file as the server assembled it. */
  sha256?: string
  expiresAt?: string
}

export interface HttpRequestConfig {
  headers?: Record<string, string>
  signal?: AbortSignal
}

/** Minimal HTTP client (axios-compatible): responses carry `{ data }`. */
export interface DataloadHttpClient {
  get(url: string, config?: HttpRequestConfig): Promise<{ data?: unknown }>
  post(url: string, body?: unknown, config?: HttpRequestConfig): Promise<{ data?: unknown }>
}

export type TranslateFn = (key: string, fallback: string) => string
